"""Build a finite later-consumer data contract and seal the actual review."""
import hashlib,json
from pathlib import Path
P=Path(__file__).resolve().parent
def row(p):
 b=p.read_bytes();return dict(path=p.relative_to(P).as_posix(),sha256=hashlib.sha256(b).hexdigest(),bytes=len(b))
def absolute(p):
 r=row(p);r['path']=str(p);return r
def write(n,d):(P/n).write_text(json.dumps(d,indent=2)+'\n')
r=json.loads((P/'results.json').read_bytes());assert r['verifiedPassed']is True and r['actualControlWorkloadsExecuted']is True and r['pilotPrerequisitesSatisfied']is False
fixed_keys=['schemaVersion','state','verifiedPassed','sourceOnly','controlSourceIndexSha256','sourceReviewIndexSha256','priorCorrectnessReviewIndexSha256','priorCorrectnessContractSha256','componentSourceIndexSha256','guestSourceIndexSha256','toolingSourceIndexSha256','sourcePublicationIndexSha256','oracleSha256','actualControlWorkloadsExecuted','allRawPrimitiveStringsCompleteAndDecoded','allFullPublicReturnExpectationsMatched','independentExpectedInputBytesAndFnvComputed','sourceCoupledNoProviderWorkloadPathVerified','allThreeOwnedWorkersRawZeroClean','externalParentExitCode','actualIndexedFiles','actualRegularFiles','actualIndexedBytes','priorControlOperations','oldV1FailureAndSourceReviewsUnchanged','independentGuestInputHeapInspection','internalCopiedBackingInspected','globalNativeCodecInstrumentation','stockWasmtimeExecuted','nodeCodecExecutedByThisAction','pilotPrerequisitesSatisfied','timingAllowed','operationalAdmission','runtimeAcceptanceClaim','actionAuthorityIssuedByReviewer','reviewerReadHashDecodeDataOnly','reviewerHelpersPreflightNodeJcoWorkerGuestCodecNativeHostTimingActionsInvoked']
exact={k:r[k]for k in ['rootReceipt','actualIndex','actualResult','actualCompletion','externalParentTerminal','rootAuthority','config','oracle']}
exact['rawReturnLedger']=absolute(P/'per-call-ledger.json');exact['expectedInputFacts']=absolute(P/'expected-input-facts.json')
for arm in r['arms']:
 for key in ['result','completion','ownedTerminal']:exact[arm['arm']+'-'+key]=arm[key]
contract=dict(schemaVersion=1,state='FINITE_ACTUAL_ZLIB_COST_JCO_CONTROL_V2_RESULT_CONTRACT_V1',requiredReviewState=r['state'],requiredFixedValues={k:r[k]for k in fixed_keys},requiredCoverage=r['coverage'],requiredExactDescriptors=exact,requiredComponents=r['requiredComponents'],requiredActualComponentReviews=r['requiredActualComponentReviews'],descriptorShape=['path','sha256','bytes'],reviewProofResultIndexedExactlyOnce=True,finiteReviewIndexRequired=True,allReviewIndexMembersRehashed=True,allActual1480OutputIndexMembersRehashedForFullProofRevalidation=True,actualOutputIndexResultCompletionAndAllWorkerTerminalBindingsRehashed=True,componentNativeOracleSourceBindingsMustMatchExactly=True,controlDomain=dict(guestControlKinds=['consumeInput','copyInputAndConsume','harnessNoCodec'],caseIds=[30,119],setupPrimaryIds=[0,29],operationsPerControlBatch=1,adjacentRepetitions=2,provedOnComponents=['native-on','fflate-on','fflate-off'],otherHostControlsOrNValuesProved=False),rawCallPartialFlagMeaning='partial:true records whole pre-assert call capture; accepted completeness also requires the immutable arm/parent completion indices and raw0/clean-owned terminal evidence.',publicObservationBoundary='All726 full primitive strings/decoded public fields checked. Input FNVs computed from independent deterministic/raw or pinned Node encoded bytes; guest FNV/sentinels/copy reports are not private input/copy heap inspections.',sourceActionPilotFlagRemainsLiteral=False,laterActionRequirements=['This contract is control correctness only; no pilot/timing/phase authority is issued.','Preserve original source-action pilotPrerequisitesSatisfied:false and timingAllowed:false.','Any later pilot/timing source needs its own complete source/API/proof contract, actual prerequisite closure, separate Root phase/quiet-window authority and fresh output.','Do not reclassify old228/control0 or v1 raw1 as these new controls.','Rehash the finite review index and every member, then exact actual index/result/completion and all1480 indexed files; check coverage/component/oracle/native/source/control domains and captured statuses, not only a state string.'],runtimeAcceptanceClaim=False,operationalAdmission=False,actionAuthorityIssuedByReviewer=False)
write('result-contract.json',contract)
write('review-receipt.json',dict(schemaVersion=1,state='SEALED_INDEPENDENT_ZLIB_COST_JCO_CONTROL_V2_RESULTS_REVIEW_PASSED_V1',controlSourceIndexSha256=r['controlSourceIndexSha256'],results=row(P/'results.json'),reader=row(P/'reader.py'),resultContract=row(P/'result-contract.json'),rawReturnLedger=row(P/'per-call-ledger.json'),verifiedPassed=True,rawReturnsDecoded=726,actualControlOperations=540,reviewerActionsReadHashDecodeOnly=True,pilotPrerequisitesSatisfied=False,timingAllowed=False,runtimeAcceptanceClaim=False,operationalAdmission=False))
write('index.json',dict(schemaVersion=1,state='SEALED_INDEPENDENT_ZLIB_COST_JCO_CONTROL_V2_RESULTS_REVIEW_PASSED_V1',files=[row(p)for p in sorted(P.rglob('*'))if p.is_file()and p!=P/'index.json'],verifiedPassed=True,reviewerActionsReadHashDecodeOnly=True,pilotPrerequisitesSatisfied=False,timingAllowed=False,runtimeAcceptanceClaim=False,operationalAdmission=False))
print(json.dumps({n:row(P/n)for n in ['index.json','results.json','result-contract.json','review-receipt.json']}))
